  for (const [name, r] of [["stack A/B", ab], ["hearth A", hA], ["hearth B", hB], ["stack B/C", bc], ["hearth B (2)", hB2], ["hearth C", hC]]) {
    if (r && r.skipped) console.warn(`chimneys: ${name} skipped ${r.skipped} cells`);
  }
}
